+            let Some((start_column, end_column)) =
+                selected_columns(selection, row, &lines[row], usize::from(pane_width))
+            else {
+                continue;
+            };
+            let start_column = start_column.min(usize::from(pane_width.saturating_sub(1)));
+            let end_column = end_column.min(usize::from(pane_width.saturating_sub(1)));
+            for column in start_column..=end_column {
+                let x = pane_x.saturating_add(column.min(usize::from(u16::MAX)) as u16);
+                let y = pane_y.saturating_add(row.min(usize::from(u16::MAX)) as u16);
+                if x < buffer.area.width && y < buffer.area.height {
